from typing import List

def tail_last_n_lines(n: int, fileContents: str) -> List[str]:
    if n <= 0 or not fileContents:
        return []
    end = len(fileContents)
    if fileContents.endswith("\n"):
        end -= 1  # 末尾换行只是最后一行的结束符，不代表多一个空行
    # 从尾部往前找第 n 个换行符，只切出需要的那一段
    start = end
    for _ in range(n):
        pos = fileContents.rfind("\n", 0, start)
        if pos == -1:
            start = 0
            break
        start = pos
    else:
        start += 1
    return fileContents[start:end].split("\n")
